def blackman_window_weight(n: int, total_n: int) -> float:
    if total_n <= 1:
        return 1.0
    idx = max(0, min(total_n - 1, n))
    denom = float(total_n - 1)
    theta = 2.0 * math.pi * float(idx) / denom
    c1 = 0.5 * math.cos(theta)
    c2 = 0.08 * math.cos(2.0 * theta)
    w = 0.42 - c1 + c2
    return max(0.0, w)

def hilbert_transform_quadrature_fir(samples: list[float], taps: int) -> list[float]:
    n_samples = len(samples)
    if n_samples == 0:
        return []
    half_m = max(1, min(16, abs(taps) // 2))
    num_taps = 2 * half_m + 1
    h = [0.0] * num_taps
    for i in range(-half_m, half_m + 1):
        if i % 2 != 0:
            val = 2.0 / (math.pi * float(i))
            w = 0.5 * (1.0 + math.cos(math.pi * float(i) / float(half_m)))
            h[i + half_m] = val * w
    out = [0.0] * n_samples
    for i in range(n_samples):
        acc = 0.0
        for j in range(num_taps):
            src_idx = i - (j - half_m)
            if 0 <= src_idx < n_samples:
                acc = acc + samples[src_idx] * h[j]
        out[i] = acc
    return out

def matched_filter_peak_detect(corr: list[float], threshold: float) -> list[int]:
    n = len(corr)
    if n < 3:
        return []
    peaks = []
    for i in range(1, n - 1):
        val = corr[i]
        if val > threshold:
            if val > corr[i - 1] and val >= corr[i + 1]:
                peaks.append(i)
    return peaks

def analytic_signal_envelope(real_part: float, imag_part: float) -> tuple[float, float]:
    re = float(real_part)
    im = float(imag_part)
    mag = math.hypot(re, im)
    phase = math.atan2(im, re)
    return (mag, phase)

def zero_crossing_rate_window(samples: list[float], threshold: float) -> float:
    n = len(samples)
    if n < 2:
        return 0.0
    thresh = max(0.0, abs(threshold))
    crossings = 0
    for i in range(1, n):
        s_prev = samples[i - 1]
        s_curr = samples[i]
        if s_prev > 0.0 and s_curr < 0.0 or (s_prev < 0.0 and s_curr > 0.0):
            if abs(s_curr - s_prev) > thresh:
                crossings = crossings + 1
    rate = float(crossings) / float(n - 1)
    return rate

def autocorrelation_lag_rxx(samples: list[float], lag: int) -> float:
    n = len(samples)
    if n == 0:
        return 0.0
    safe_lag = min(n - 1, max(0, abs(lag)))
    r0 = sum((x * x for x in samples))
    if r0 < 1e-15:
        return 0.0
    r_lag = sum((samples[i] * samples[i + safe_lag] for i in range(n - safe_lag)))
    coeff = r_lag / r0
    return max(-1.0, min(1.0, coeff))

def yule_walker_levinson_durbin(r: list[float], order: int) -> tuple[list[float], float]:
    p = max(1, min(len(r) - 1, abs(order))) if len(r) > 1 else 0
    if p == 0:
        return ([1.0], r[0] if len(r) > 0 else 1.0)
    e = r[0] if r[0] > 1e-12 else 1e-12
    a = [1.0]
    for m in range(1, p + 1):
        s = sum((a[j] * r[m - j] for j in range(1, m)))
        rm = r[m] if m < len(r) else 0.0
        km = -(rm + s) / e
        km_clamped = max(-0.999, min(0.999, km))
        a_new = [1.0] + [0.0] * m
        for j in range(1, m):
            a_new[j] = a[j] + km_clamped * a[m - j]
        a_new[m] = km_clamped
        a = a_new
        e = e * (1.0 - km_clamped * km_clamped)
        if e < 1e-15:
            e = 1e-15
            break
    return (a, e)

def lpc_prediction_residual(samples: list[float], coeffs: list[float]) -> list[float]:
    n = len(samples)
    if n == 0:
        return []
    p = len(coeffs) - 1
    if p < 1:
        return list(samples)
    a0 = coeffs[0] if abs(coeffs[0]) > 1e-12 else 1.0
    norm_a = [c / a0 for c in coeffs]
    res = [0.0] * n
    for i in range(n):
        pred = sum((norm_a[k] * samples[i - k] for k in range(1, min(i + 1, len(norm_a)))))
        res[i] = samples[i] + pred
    return res

def mel_filterbank_triangle_weight(freq: float, f_low: float, f_center: float, f_high: float) -> float:
    if freq < f_low or freq > f_high:
        return 0.0
    denom_left = max(1e-12, f_center - f_low)
    denom_right = max(1e-12, f_high - f_center)
    if freq <= f_center:
        w = (freq - f_low) / denom_left
    else:
        w = (f_high - freq) / denom_right
    return max(0.0, min(1.0, w))

def allpass_first_order_step(x: float, x_prev: float, y_prev: float, a: float) -> tuple[float, float, float]:
    safe_a = max(-0.999, min(0.999, float(a)))
    y = safe_a * x + x_prev - safe_a * y_prev
    new_x_prev = x
    new_y_prev = y
    return (y, new_x_prev, new_y_prev)

def downsample_anti_alias_decimate(samples: list[float], factor: int) -> list[float]:
    n = len(samples)
    if n == 0:
        return []
    stride = max(1, abs(factor))
    decimated = []
    for i in range(0, n, stride):
        decimated.append(samples[i])
    return decimated

def upsample_zero_insert(samples: list[float], factor: int) -> list[float]:
    n = len(samples)
    if n == 0:
        return []
    f = max(1, min(16, abs(int(factor))))
    out = []
    max_len = 512
    for x in samples[:max_len]:
        out.append(float(x))
        for _ in range(f - 1):
            out.append(0.0)
    return out

def circular_shift_signal(samples: list[float], shift: int) -> list[float]:
    n = len(samples)
    if n == 0:
        return []
    eff_shift = shift % n
    out = [0.0] * n
    for i in range(n):
        new_idx = (i + eff_shift) % n
        out[new_idx] = samples[i]
    return out
